// Reads contract/agent.schema.json and emits the typed frontend surface.
// Usage: node scripts/gen-contract-types.mjs [--check]
// --check exits non-zero when the generated file is stale (used by CI).
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const schemaPath = resolve(here, '../contract/agent.schema.json');
const outPath = resolve(here, '../src/Web.Client/src/contract/agent.d.ts');

function unionOf(values) {
  return values.map((v) => JSON.stringify(v)).join(' | ');
}

function render(schema) {
  const version = schema.contractVersion;
  const methods = schema.methods;
  const events = schema.events;
  const codes = schema.errorCodes;
  return `// generated by scripts/gen-contract-types.mjs from contract/agent.schema.json — do not edit by hand.
export const CONTRACT_VERSION = ${JSON.stringify(version)};

export type ContractMethod = ${unionOf(methods)};

export type ContractEventKind = ${unionOf(events)};

export type ContractErrorCode = ${unionOf(codes)};

export interface ContractRequestFrame {
  t: 'req';
  id: number;
  m: ContractMethod;
  p?: Record<string, unknown>;
}

export interface ContractResponseFrame {
  t: 'res';
  id: number;
  ok: boolean;
  r?: Record<string, unknown>;
  e?: {
    code: ContractErrorCode;
    msg: string;
    hint?: string;
  };
}

export interface ContractEventFrame {
  t: 'evt';
  seq: number;
  k: ContractEventKind;
  p?: Record<string, unknown>;
}

export type ContractFrame = ContractRequestFrame | ContractResponseFrame | ContractEventFrame;
`;
}

const schema = JSON.parse(readFileSync(schemaPath, 'utf8'));
for (const key of ['contractVersion', 'methods', 'events', 'errorCodes']) {
  if (schema[key] === undefined) {
    console.error(`schema is missing required top-level key: ${key}`);
    process.exit(1);
  }
}
const text = render(schema);

if (process.argv.includes('--check')) {
  const current = readFileSync(outPath, 'utf8');
  if (current !== text) {
    console.error('generated contract types are stale: rerun node scripts/gen-contract-types.mjs');
    process.exit(1);
  }
  console.log('contract types are fresh.');
} else {
  writeFileSync(outPath, text);
  console.log(`wrote ${outPath}`);
}
